from marshmallow import EXCLUDE, Schema, ValidationError, fields, validates


class SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(missing="free")
    age = fields.Integer(validate=lambda n: 16 <= n <= 120, required=False)

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', or 'team'.")


class SignupError(ValueError):
    def __init__(self, messages):
        super().__init__("invalid signup data: %s" % (messages,))
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """Validate sign-up data dict; returns cleaned dict or raises ValueError(messages)."""
    try:
        return SignupSchema().load(data)
    except ValidationError as err:
        raise SignupError(err.messages)

